input.query:
MATCH (r:Recall)-[:RECALLS_PRODUCT]->(q:Product)
WHERE q.product_ndc = '11797-759' OR EXISTS { MATCH (q)-[:INGREDIENT]->(:Substance)<-[:INGREDIENT]-(:Product {product_ndc:'11797-759'}) }
RETURN DISTINCT r.iri, r.recall_number, r.classification, r.report_date, q.product_ndc

